import { type AnchorSpec, type Placement, type PositionSpec } from './overlay-spec';

export interface ViewportRect {
  readonly width: number;
  readonly height: number;
}

export interface Rect {
  readonly left: number;
  readonly top: number;
  readonly right: number;
  readonly bottom: number;
  readonly width: number;
  readonly height: number;
}

export interface Point {
  readonly x: number;
  readonly y: number;
}

export interface OverlaySize {
  readonly width: number;
  readonly height: number;
}

export interface OverlayCoordinates {
  readonly left: number;
  readonly top: number;
  readonly placement: Placement;
}

export function getViewportRect(): ViewportRect {
  const docEl = document.documentElement;
  const width = docEl?.clientWidth || window.innerWidth;
  const height = docEl?.clientHeight || window.innerHeight;
  return { width, height };
}

export function getContainerRect(container: HTMLElement): Rect {
  return rectFromDom(container.getBoundingClientRect());
}

export function rectFromDom(domRect: DOMRect): Rect {
  return {
    left: domRect.left,
    top: domRect.top,
    right: domRect.right,
    bottom: domRect.bottom,
    width: domRect.width,
    height: domRect.height,
  };
}

export function getAnchorRect(anchor: AnchorSpec, viewport: ViewportRect): Rect {
  switch (anchor.kind) {
    case 'element':
      return rectFromDom(anchor.element.getBoundingClientRect());
    case 'point':
      return rectFromPoint(anchor, 0, 0);
    case 'virtual':
      return rectFromVirtual(anchor, viewport);
  }
}

export function rectFromPoint(point: Point, width: number, height: number): Rect {
  const left = point.x;
  const top = point.y;
  return {
    left,
    top,
    right: left + width,
    bottom: top + height,
    width,
    height,
  };
}

export function rectFromVirtual(
  spec: Extract<AnchorSpec, { kind: 'virtual' }>,
  viewport: ViewportRect
): Rect {
  if (spec.placement === 'center') {
    const x = viewport.width / 2;
    const y = viewport.height / 2;
    return rectFromPoint({ x, y }, 0, 0);
  }

  if (spec.placement === 'top') {
    const x = viewport.width / 2;
    const y = 0;
    return rectFromPoint({ x, y }, 0, 0);
  }

  const x = viewport.width / 2;
  const y = viewport.height;
  return rectFromPoint({ x, y }, 0, 0);
}

export function getScrollParents(element: Element): Array<Element | Window> {
  const result: Array<Element | Window> = [];

  let current: Element | null = element;
  while (current && current.parentElement) {
    current = current.parentElement;
    const style = getComputedStyle(current);
    const overflowY = style.overflowY;
    const overflowX = style.overflowX;

    const scrollable =
      overflowY === 'auto' ||
      overflowY === 'scroll' ||
      overflowX === 'auto' ||
      overflowX === 'scroll';

    if (scrollable) {
      result.push(current);
    }
  }

  result.push(window);
  return result;
}

export function computeOverlayCoordinates(
  anchorRect: Rect,
  overlaySize: OverlaySize,
  position: PositionSpec,
  viewport: ViewportRect,
  boundaryRect?: Rect
): OverlayCoordinates {
  const placements: readonly Placement[] = Array.isArray(position.placement)
    ? position.placement
    : [position.placement];

  const offset = position.offset ?? 0;
  const allowFlip = position.flip ?? false;
  const allowShift = position.shift ?? false;

  // Use container boundaries if provided, otherwise use viewport
  const boundary = boundaryRect ?? { left: 0, top: 0, right: viewport.width, bottom: viewport.height, width: viewport.width, height: viewport.height };

  const candidates = placements.map((placement) => ({
    placement,
    coords: coordsForPlacement(anchorRect, overlaySize, placement, offset),
  }));

  if (allowFlip) {
    for (const candidate of candidates) {
      const fits = fitsInBoundary(candidate.coords, overlaySize, boundary);
      if (fits) {
        return allowShift
          ? { ...shiftIntoBoundary(candidate.coords, overlaySize, boundary), placement: candidate.placement }
          : { ...candidate.coords, placement: candidate.placement };
      }
    }
  }

  // Choose the candidate with the smallest total overflow.
  let best = candidates[0];
  let bestOverflow = Number.POSITIVE_INFINITY;

  for (const candidate of candidates) {
    const overflow = totalOverflowFromBoundary(candidate.coords, overlaySize, boundary);
    if (overflow < bestOverflow) {
      best = candidate;
      bestOverflow = overflow;
    }
  }

  const chosen =
    best?.coords ??
    coordsForPlacement(anchorRect, overlaySize, placements[0] ?? 'bottom', offset);

  const shifted = allowShift ? shiftIntoBoundary(chosen, overlaySize, boundary) : chosen;
  return { ...shifted, placement: best?.placement ?? (placements[0] ?? 'bottom') };
}

function coordsForPlacement(
  anchorRect: Rect,
  overlaySize: OverlaySize,
  placement: Placement,
  offset: number
): { left: number; top: number } {
  const anchorCenterX = anchorRect.left + anchorRect.width / 2;
  const anchorCenterY = anchorRect.top + anchorRect.height / 2;

  switch (placement) {
    case 'center':
      return {
        left: anchorCenterX - overlaySize.width / 2,
        top: anchorCenterY - overlaySize.height / 2,
      };

    case 'top':
      return {
        left: anchorCenterX - overlaySize.width / 2,
        top: anchorRect.top - overlaySize.height - offset,
      };
    case 'top-start':
      return {
        left: anchorRect.left,
        top: anchorRect.top - overlaySize.height - offset,
      };
    case 'top-end':
      return {
        left: anchorRect.right - overlaySize.width,
        top: anchorRect.top - overlaySize.height - offset,
      };

    case 'bottom':
      return {
        left: anchorCenterX - overlaySize.width / 2,
        top: anchorRect.bottom + offset,
      };
    case 'bottom-start':
      return {
        left: anchorRect.left,
        top: anchorRect.bottom + offset,
      };
    case 'bottom-end':
      return {
        left: anchorRect.right - overlaySize.width,
        top: anchorRect.bottom + offset,
      };

    case 'left':
      return {
        left: anchorRect.left - overlaySize.width - offset,
        top: anchorCenterY - overlaySize.height / 2,
      };
    case 'left-start':
      return {
        left: anchorRect.left - overlaySize.width - offset,
        top: anchorRect.top,
      };
    case 'left-end':
      return {
        left: anchorRect.left - overlaySize.width - offset,
        top: anchorRect.bottom - overlaySize.height,
      };

    case 'right':
      return {
        left: anchorRect.right + offset,
        top: anchorCenterY - overlaySize.height / 2,
      };
    case 'right-start':
      return {
        left: anchorRect.right + offset,
        top: anchorRect.top,
      };
    case 'right-end':
      return {
        left: anchorRect.right + offset,
        top: anchorRect.bottom - overlaySize.height,
      };
  }
}

function fitsInBoundary(
  coords: { left: number; top: number },
  overlaySize: OverlaySize,
  boundary: Rect
): boolean {
  return (
    coords.left >= boundary.left &&
    coords.top >= boundary.top &&
    coords.left + overlaySize.width <= boundary.right &&
    coords.top + overlaySize.height <= boundary.bottom
  );
}

function shiftIntoBoundary(
  coords: { left: number; top: number },
  overlaySize: OverlaySize,
  boundary: Rect
): { left: number; top: number } {
  const maxLeft = Math.max(boundary.left, boundary.right - overlaySize.width);
  const maxTop = Math.max(boundary.top, boundary.bottom - overlaySize.height);

  return {
    left: clamp(coords.left, boundary.left, maxLeft),
    top: clamp(coords.top, boundary.top, maxTop),
  };
}

function totalOverflowFromBoundary(
  coords: { left: number; top: number },
  overlaySize: OverlaySize,
  boundary: Rect
): number {
  const leftOverflow = Math.max(0, boundary.left - coords.left);
  const topOverflow = Math.max(0, boundary.top - coords.top);
  const rightOverflow = Math.max(0, coords.left + overlaySize.width - boundary.right);
  const bottomOverflow = Math.max(0, coords.top + overlaySize.height - boundary.bottom);

  return leftOverflow + topOverflow + rightOverflow + bottomOverflow;
}

function clamp(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

import {
  ApplicationRef,
  EnvironmentInjector,
  Injectable,
  TemplateRef,
  Type,
  inject,
} from '@angular/core';
import {
  COAR_OVERLAY_DEFAULTS,
  COAR_OVERLAY_SPEC_RESOLVERS,
  type ContentSpec,
  type OverlaySpec,
  type OverlaySpecResolver,
  type ResolvedOverlaySpec,
} from './overlay-spec';
import { type OverlayRef } from './overlay-ref';
import { CoarOverlayRef } from './overlay-ref-impl';

export interface OverlayOpenOptions {
  closeSiblings?: boolean;
}

export type OverlaySettings<TInputs> = Omit<OverlaySpec<TInputs>, 'content'>;

type UnwrapInputSignal<T> = T extends import('@angular/core').InputSignal<infer V> ? V : T;

export type ComponentInputs<C> = {
  [K in keyof C]?: UnwrapInputSignal<C[K]>;
};

export interface OverlayAsChildOptions {
  closeSiblings?: boolean;
}

@Injectable({ providedIn: 'root' })
export class CoarOverlayService {
  private readonly appRef = inject(ApplicationRef);
  private readonly environmentInjector = inject(EnvironmentInjector);

  private readonly specResolvers =
    inject(COAR_OVERLAY_SPEC_RESOLVERS, { optional: true }) ??
    ([] as const satisfies readonly OverlaySpecResolver[]);

  private readonly openOverlays = new Set<CoarOverlayRef>();

  private globalListenersInstalled = false;

  private readonly onDocumentPointerDown = (event: PointerEvent) => {
    const overlays = this.getOpenOverlaysInOrder();
    if (overlays.length === 0) return;

    const target = event.target;
    const topmostContaining = this.getTopmostOverlayContainingTarget(target);
    if (topmostContaining) {
      // When interacting with an overlay, close any child overlays (submenus) that may be open.
      topmostContaining.closeChildren();
      return;
    }

    const topmost = this.getTopmostDismissableOverlay('outsideClick');
    if (!topmost) return;

    // For overlay trees (e.g. menus + submenus), outside-click should close the entire tree.
    const root = topmost.getRoot();
    if (root !== topmost && root.isDismissable('outsideClick')) {
      root.close();
      return;
    }

    topmost.close();
  };

  private readonly onDocumentKeyDown = (event: KeyboardEvent) => {
    if (event.key === 'Escape') {
      const topmost = this.getTopmostDismissableOverlay('escapeKey');
      if (!topmost) return;

      event.preventDefault();
      event.stopPropagation();
      topmost.close();
      return;
    }

    if (event.key === 'Tab') {
      const topmost = this.getTopmostFocusTrappingOverlay();
      if (!topmost) return;

      if (topmost.handleTabKey(event)) {
        event.preventDefault();
      }
    }
  };

  openTemplate<TCtx>(
    template: TemplateRef<TCtx>,
    settings: OverlaySettings<TCtx>,
    inputs: TCtx
  ): OverlayRef {
    const resolved = this.resolveSpec({
      ...settings,
      content: { kind: 'template', template },
    });

    return this.attach(resolved, inputs, undefined);
  }

  openComponent<C>(
    component: Type<C>,
    settings: OverlaySettings<ComponentInputs<C>>,
    inputs: ComponentInputs<C>
  ): OverlayRef {
    const resolved = this.resolveSpec({
      ...settings,
      content: { kind: 'component', component },
    });

    return this.attach(resolved, inputs, undefined);
  }

  openText(settings: OverlaySettings<{ text: string }>, inputs: { text: string }): OverlayRef {
    const resolved = this.resolveSpec({
      ...settings,
      content: { kind: 'text' },
    });

    return this.attach(resolved, inputs, undefined);
  }

  openTemplateAsChild<TCtx>(
    parent: OverlayRef,
    template: TemplateRef<TCtx>,
    settings: OverlaySettings<TCtx>,
    inputs: TCtx,
    options?: OverlayOpenOptions
  ): OverlayRef {
    const resolved = this.resolveSpec({
      ...settings,
      content: { kind: 'template', template },
    });

    return this.attach(resolved, inputs, { parent, closeSiblings: options?.closeSiblings });
  }

  openComponentAsChild<C>(
    parent: OverlayRef,
    component: Type<C>,
    settings: OverlaySettings<ComponentInputs<C>>,
    inputs: ComponentInputs<C>,
    options?: OverlayOpenOptions
  ): OverlayRef {
    const resolved = this.resolveSpec({
      ...settings,
      content: { kind: 'component', component },
    });

    return this.attach(resolved, inputs, { parent, closeSiblings: options?.closeSiblings });
  }

  openTextAsChild(
    parent: OverlayRef,
    settings: OverlaySettings<{ text: string }>,
    inputs: { text: string },
    options?: OverlayOpenOptions
  ): OverlayRef {
    const resolved = this.resolveSpec({
      ...settings,
      content: { kind: 'text' },
    });

    return this.attach(resolved, inputs, { parent, closeSiblings: options?.closeSiblings });
  }

  closeAll(): void {
    for (const ref of Array.from(this.openOverlays)) {
      ref.close();
    }
  }

  private resolveSpec<TInputs>(spec: OverlaySpec<TInputs>): ResolvedOverlaySpec<TInputs> {
    const resolvedSpec = this.applySpecResolvers(spec);

    const content = resolvedSpec.content;
    if (!content) {
      throw new Error('OverlaySpec missing content');
    }

    return {
      content,
      anchor: resolvedSpec.anchor ?? COAR_OVERLAY_DEFAULTS.anchor,
      position: resolvedSpec.position ?? COAR_OVERLAY_DEFAULTS.position,
      size: resolvedSpec.size ?? { mode: 'content' },
      backdrop: resolvedSpec.backdrop ?? COAR_OVERLAY_DEFAULTS.backdrop,
      scroll: resolvedSpec.scroll ?? COAR_OVERLAY_DEFAULTS.scroll,
      dismiss: resolvedSpec.dismiss ?? COAR_OVERLAY_DEFAULTS.dismiss,
      focus: resolvedSpec.focus ?? COAR_OVERLAY_DEFAULTS.focus,
      a11y: resolvedSpec.a11y ?? COAR_OVERLAY_DEFAULTS.a11y,
      attachment: resolvedSpec.attachment ?? COAR_OVERLAY_DEFAULTS.attachment,
    };
  }

  private applySpecResolvers<TInputs>(spec: OverlaySpec<TInputs>): OverlaySpec<TInputs> {
    if (this.specResolvers.length === 0) return spec;

    let current = spec as unknown as OverlaySpec<unknown>;
    for (const resolver of this.specResolvers) {
      const next = resolver(current);
      current = (next ?? current) as OverlaySpec<unknown>;
    }

    return current as unknown as OverlaySpec<TInputs>;
  }

  private attach<TInputs>(
    spec: ResolvedOverlaySpec<TInputs>,
    inputs: TInputs,
    options?: { parent?: OverlayRef; closeSiblings?: boolean }
  ): OverlayRef {
    const parent = this.getInternalRefOrNull(options?.parent);

    // Close sibling overlays if requested (close all existing children of parent)
    if (options?.closeSiblings && parent) {
      parent.closeChildren();
    }

    const stackIndex = this.openOverlays.size;

    const effectiveSpec = this.inheritDismissFromParent(spec, parent);

    const ref = new CoarOverlayRef(
      this.appRef,
      this.environmentInjector,
      effectiveSpec,
      this.mergeInputs(spec.content, inputs),
      stackIndex,
      parent,
      () => {
        this.openOverlays.delete(ref);
        this.uninstallGlobalListenersIfIdle();
      }
    );

    this.openOverlays.add(ref);
    this.installGlobalListenersIfNeeded();
    ref.open();
    return ref;
  }

  private inheritDismissFromParent<TInputs>(
    spec: ResolvedOverlaySpec<TInputs>,
    parent: CoarOverlayRef | null
  ): ResolvedOverlaySpec<TInputs> {
    if (!parent) return spec;

    const parentHoverTree = parent.getHoverTreeDismissConfig();
    if (!parentHoverTree?.enabled) return spec;

    const childHoverTree = spec.dismiss.hoverTree;

    // Explicit disable in child wins.
    if (childHoverTree?.enabled === false) return spec;

    let mergedHoverTree: typeof childHoverTree;
    if (!childHoverTree) {
      mergedHoverTree = { ...parentHoverTree };
    } else {
      mergedHoverTree = {
        enabled: true,
        delayMs: childHoverTree.delayMs ?? parentHoverTree.delayMs,
      };
    }

    // No change.
    if (mergedHoverTree === childHoverTree) return spec;

    return {
      ...(spec as unknown as object),
      dismiss: {
        ...(spec.dismiss as object),
        hoverTree: mergedHoverTree,
      },
    } as ResolvedOverlaySpec<TInputs>;
  }

  private getInternalRefOrNull(ref: OverlayRef | undefined): CoarOverlayRef | null {
    if (!ref) return null;
    if (ref instanceof CoarOverlayRef) return ref;
    return null;
  }

  private installGlobalListenersIfNeeded(): void {
    if (this.globalListenersInstalled) return;
    if (typeof document === 'undefined') return;

    document.addEventListener('pointerdown', this.onDocumentPointerDown, { capture: true });
    document.addEventListener('keydown', this.onDocumentKeyDown, { capture: true });
    this.globalListenersInstalled = true;
  }

  private uninstallGlobalListenersIfIdle(): void {
    if (!this.globalListenersInstalled) return;
    if (this.openOverlays.size > 0) return;
    if (typeof document === 'undefined') return;

    document.removeEventListener('pointerdown', this.onDocumentPointerDown, { capture: true });
    document.removeEventListener('keydown', this.onDocumentKeyDown, { capture: true });
    this.globalListenersInstalled = false;
  }

  private getOpenOverlaysInOrder(): CoarOverlayRef[] {
    return Array.from(this.openOverlays);
  }

  private getTopmostOverlayContainingTarget(target: EventTarget | null): CoarOverlayRef | null {
    const overlays = this.getOpenOverlaysInOrder();

    for (let i = overlays.length - 1; i >= 0; i -= 1) {
      const overlay = overlays[i];
      if (overlay.containsEventTarget(target)) return overlay;
    }

    return null;
  }

  private getTopmostDismissableOverlay(kind: 'outsideClick' | 'escapeKey'): CoarOverlayRef | null {
    const overlays = this.getOpenOverlaysInOrder();

    for (let i = overlays.length - 1; i >= 0; i -= 1) {
      const overlay = overlays[i];
      if (overlay.isDismissable(kind)) {
        return overlay;
      }
    }

    return null;
  }

  private getTopmostFocusTrappingOverlay(): CoarOverlayRef | null {
    const overlays = this.getOpenOverlaysInOrder();

    for (let i = overlays.length - 1; i >= 0; i -= 1) {
      const overlay = overlays[i];
      if (overlay.hasFocusTrap()) {
        return overlay;
      }
    }

    return null;
  }

  private mergeInputs<TInputs>(content: ContentSpec<TInputs>, inputs: TInputs): TInputs {
    if (!content.defaults) return inputs;

    if (inputs == null || typeof inputs !== 'object') {
      return { ...(content.defaults as object) } as TInputs;
    }

    return {
      ...(content.defaults as object),
      ...(inputs as object),
    } as TInputs;
  }
}

import { Observable } from 'rxjs';

export interface OverlayRef {
  close(result?: unknown): void;
  updatePosition(): void;
  closeChildren(exclude?: OverlayRef): void;
  readonly afterClosed$: Observable<unknown>;
  readonly isClosed: boolean;

  /**
   * Get the root overlay in a parent-child tree (e.g., menu with submenus).
   * Returns this overlay if it has no parent.
   */
  getRoot(): OverlayRef;

  /**
   * Optional DOM access for advanced behaviors (e.g. menu-aim).
   * Implementations may return the inner panel element that contains the rendered content.
   */
  getPanelElement?(): HTMLElement;
}

import { type AnchorSpec, type Placement, type PositionSpec } from './overlay-spec';

export interface ViewportRect {
  readonly width: number;
  readonly height: number;
}

export interface Rect {
  readonly left: number;
  readonly top: number;
  readonly right: number;
  readonly bottom: number;
  readonly width: number;
  readonly height: number;
}

export interface Point {
  readonly x: number;
  readonly y: number;
}

export interface OverlaySize {
  readonly width: number;
  readonly height: number;
}

export interface OverlayCoordinates {
  readonly left: number;
  readonly top: number;
  readonly placement: Placement;
}

export function getViewportRect(): ViewportRect {
  const docEl = document.documentElement;
  const width = docEl?.clientWidth || window.innerWidth;
  const height = docEl?.clientHeight || window.innerHeight;
  return { width, height };
}

export function getContainerRect(container: HTMLElement): Rect {
  return rectFromDom(container.getBoundingClientRect());
}

export function rectFromDom(domRect: DOMRect): Rect {
  return {
    left: domRect.left,
    top: domRect.top,
    right: domRect.right,
    bottom: domRect.bottom,
    width: domRect.width,
    height: domRect.height,
  };
}

export function getAnchorRect(anchor: AnchorSpec, viewport: ViewportRect): Rect {
  switch (anchor.kind) {
    case 'element':
      return rectFromDom(anchor.element.getBoundingClientRect());
    case 'point':
      return rectFromPoint(anchor, 0, 0);
    case 'virtual':
      return rectFromVirtual(anchor, viewport);
  }
}

export function rectFromPoint(point: Point, width: number, height: number): Rect {
  const left = point.x;
  const top = point.y;
  return {
    left,
    top,
    right: left + width,
    bottom: top + height,
    width,
    height,
  };
}

export function rectFromVirtual(
  spec: Extract<AnchorSpec, { kind: 'virtual' }>,
  viewport: ViewportRect
): Rect {
  if (spec.placement === 'center') {
    const x = viewport.width / 2;
    const y = viewport.height / 2;
    return rectFromPoint({ x, y }, 0, 0);
  }

  if (spec.placement === 'top') {
    const x = viewport.width / 2;
    const y = 0;
    return rectFromPoint({ x, y }, 0, 0);
  }

  const x = viewport.width / 2;
  const y = viewport.height;
  return rectFromPoint({ x, y }, 0, 0);
}

export function getScrollParents(element: Element): Array<Element | Window> {
  const result: Array<Element | Window> = [];

  let current: Element | null = element;
  while (current && current.parentElement) {
    current = current.parentElement;
    const style = getComputedStyle(current);
    const overflowY = style.overflowY;
    const overflowX = style.overflowX;

    const scrollable =
      overflowY === 'auto' ||
      overflowY === 'scroll' ||
      overflowX === 'auto' ||
      overflowX === 'scroll';

    if (scrollable) {
      result.push(current);
    }
  }

  result.push(window);
  return result;
}

export function computeOverlayCoordinates(
  anchorRect: Rect,
  overlaySize: OverlaySize,
  position: PositionSpec,
  viewport: ViewportRect,
  boundaryRect?: Rect
): OverlayCoordinates {
  const placements: readonly Placement[] = Array.isArray(position.placement)
    ? position.placement
    : [position.placement];

  const offset = position.offset ?? 0;
  const allowFlip = position.flip ?? false;
  const allowShift = position.shift ?? false;

  // Use container boundaries if provided, otherwise use viewport
  const boundary = boundaryRect ?? { left: 0, top: 0, right: viewport.width, bottom: viewport.height, width: viewport.width, height: viewport.height };

  const candidates = placements.map((placement) => ({
    placement,
    coords: coordsForPlacement(anchorRect, overlaySize, placement, offset),
  }));

  if (allowFlip) {
    for (const candidate of candidates) {
      const fits = fitsInBoundary(candidate.coords, overlaySize, boundary);
      if (fits) {
        return allowShift
          ? { ...shiftIntoBoundary(candidate.coords, overlaySize, boundary), placement: candidate.placement }
          : { ...candidate.coords, placement: candidate.placement };
      }
    }
  }

  // Choose the candidate with the smallest total overflow.
  let best = candidates[0];
  let bestOverflow = Number.POSITIVE_INFINITY;

  for (const candidate of candidates) {
    const overflow = totalOverflowFromBoundary(candidate.coords, overlaySize, boundary);
    if (overflow < bestOverflow) {
      best = candidate;
      bestOverflow = overflow;
    }
  }

  const chosen =
    best?.coords ??
    coordsForPlacement(anchorRect, overlaySize, placements[0] ?? 'bottom', offset);

  const shifted = allowShift ? shiftIntoBoundary(chosen, overlaySize, boundary) : chosen;
  return { ...shifted, placement: best?.placement ?? (placements[0] ?? 'bottom') };
}

function coordsForPlacement(
  anchorRect: Rect,
  overlaySize: OverlaySize,
  placement: Placement,
  offset: number
): { left: number; top: number } {
  const anchorCenterX = anchorRect.left + anchorRect.width / 2;
  const anchorCenterY = anchorRect.top + anchorRect.height / 2;

  switch (placement) {
    case 'center':
      return {
        left: anchorCenterX - overlaySize.width / 2,
        top: anchorCenterY - overlaySize.height / 2,
      };

    case 'top':
      return {
        left: anchorCenterX - overlaySize.width / 2,
        top: anchorRect.top - overlaySize.height - offset,
      };
    case 'top-start':
      return {
        left: anchorRect.left,
        top: anchorRect.top - overlaySize.height - offset,
      };
    case 'top-end':
      return {
        left: anchorRect.right - overlaySize.width,
        top: anchorRect.top - overlaySize.height - offset,
      };

    case 'bottom':
      return {
        left: anchorCenterX - overlaySize.width / 2,
        top: anchorRect.bottom + offset,
      };
    case 'bottom-start':
      return {
        left: anchorRect.left,
        top: anchorRect.bottom + offset,
      };
    case 'bottom-end':
      return {
        left: anchorRect.right - overlaySize.width,
        top: anchorRect.bottom + offset,
      };

    case 'left':
      return {
        left: anchorRect.left - overlaySize.width - offset,
        top: anchorCenterY - overlaySize.height / 2,
      };
    case 'left-start':
      return {
        left: anchorRect.left - overlaySize.width - offset,
        top: anchorRect.top,
      };
    case 'left-end':
      return {
        left: anchorRect.left - overlaySize.width - offset,
        top: anchorRect.bottom - overlaySize.height,
      };

    case 'right':
      return {
        left: anchorRect.right + offset,
        top: anchorCenterY - overlaySize.height / 2,
      };
    case 'right-start':
      return {
        left: anchorRect.right + offset,
        top: anchorRect.top,
      };
    case 'right-end':
      return {
        left: anchorRect.right + offset,
        top: anchorRect.bottom - overlaySize.height,
      };
  }
}

function fitsInBoundary(
  coords: { left: number; top: number },
  overlaySize: OverlaySize,
  boundary: Rect
): boolean {
  return (
    coords.left >= boundary.left &&
    coords.top >= boundary.top &&
    coords.left + overlaySize.width <= boundary.right &&
    coords.top + overlaySize.height <= boundary.bottom
  );
}

function shiftIntoBoundary(
  coords: { left: number; top: number },
  overlaySize: OverlaySize,
  boundary: Rect
): { left: number; top: number } {
  const maxLeft = Math.max(boundary.left, boundary.right - overlaySize.width);
  const maxTop = Math.max(boundary.top, boundary.bottom - overlaySize.height);

  return {
    left: clamp(coords.left, boundary.left, maxLeft),
    top: clamp(coords.top, boundary.top, maxTop),
  };
}

function totalOverflowFromBoundary(
  coords: { left: number; top: number },
  overlaySize: OverlaySize,
  boundary: Rect
): number {
  const leftOverflow = Math.max(0, boundary.left - coords.left);
  const topOverflow = Math.max(0, boundary.top - coords.top);
  const rightOverflow = Math.max(0, coords.left + overlaySize.width - boundary.right);
  const bottomOverflow = Math.max(0, coords.top + overlaySize.height - boundary.bottom);

  return leftOverflow + topOverflow + rightOverflow + bottomOverflow;
}

function clamp(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

import { type AnchorSpec, type Placement, type PositionSpec } from './overlay-spec';

export interface ViewportRect {
  readonly width: number;
  readonly height: number;
}

export interface Rect {
  readonly left: number;
  readonly top: number;
  readonly right: number;
  readonly bottom: number;
  readonly width: number;
  readonly height: number;
}

export interface Point {
  readonly x: number;
  readonly y: number;
}

export interface OverlaySize {
  readonly width: number;
  readonly height: number;
}

export interface OverlayCoordinates {
